def random_hotline():
    return "09" + str(random.randint(10000000, 99999999))


def random_price_by_type(accommodation_type, room_type):
    if accommodation_type == "hostel":
        return random.randint(120000, 700000)

    if accommodation_type == "homestay":
        return random.randint(250000, 1500000)

    if accommodation_type == "apartment":
        return random.randint(500000, 2500000)

    if accommodation_type == "hotel":
        if room_type in ["suite", "deluxe"]:
            return random.randint(900000, 3000000)

        return random.randint(300000, 1800000)

    return random.randint(180000, 2500000)


def random_capacity_by_type(accommodation_type):
    if accommodation_type == "hostel":
        return random.randint(1, 12)

    if accommodation_type == "apartment":
        return random.randint(2, 8)

    if accommodation_type == "homestay":
        return random.randint(2, 10)

    return random.randint(1, 8)


