for i, item in enumerate(accommodation_data, start=1):
    acc_type = item.get("accommodation_type") or "hotel"
    capacity = random_capacity_by_type(acc_type)

    area = item.get("area") or random.choice(valid_areas)

    if area not in valid_areas:
        area = random.choice(valid_areas)

    accommodation = Accommodation.objects.create(
        accommodation_code=item.get("accommodation_code") or f"CRAWL-{i:04}",
        name=item.get("name") or f"Accommodation {i}",
        accommodation_type=acc_type,
        area=area,
        address=item.get("address") or "",
        price_per_night=0,
        capacity=capacity,
        rating=item.get("rating") or 0,
        review_count=item.get("review_count") or 0,
        latitude=item.get("latitude"),
        longitude=item.get("longitude"),
        amenities=random.sample(amenities_list, k=random.randint(2, 5)),
        description=f"{acc_type.title()} tiện nghi, phù hợp nghỉ ngắn ngày và du lịch.",
        hotline=item.get("hotline") or random_hotline(),
        image_url=item.get("image_url") or f"https://picsum.photos/seed/accommodation{i}/800/500"
    )

    available_room_types = room_types_by_accommodation_type.get(
        acc_type,
        ["single", "double", "twin", "family", "deluxe"]
    )

    so_loai_phong = random.randint(2, min(5, len(available_room_types)))
    selected_room_types = random.sample(available_room_types, k=so_loai_phong)

    room_prices = []

    for j, room_type in enumerate(selected_room_types, start=1):
        room_price = random_price_by_type(acc_type, room_type)
        room_capacity = random.randint(1, max(1, capacity))
        total_rooms = random.randint(3, 15)
        available_rooms = random.randint(0, total_rooms)

        Room.objects.create(
            accommodation=accommodation,
            room_code=f"{accommodation.accommodation_code}-R{j:02}",
            room_type=room_type,
            name=random.choice(room_name_map.get(room_type, ["Phòng mặc định"])),
            price_per_night=room_price,
            capacity=room_capacity,
            total_rooms=total_rooms,
            available_rooms=available_rooms,
            amenities=random.sample(amenities_list, k=random.randint(2, 5)),
            description=f"{room_type.title()} room với đầy đủ tiện nghi cơ bản.",
            is_active=True
        )

        room_prices.append(room_price)

    if room_prices:
        accommodation.price_per_night = sum(room_prices) // len(room_prices)
        accommodation.save(update_fields=["price_per_night"])


print(f"✅ Đã seed {len(accommodation_data)} accommodations thành công!")